                            },
                        )
                    ],
                ),
                # Milestone 1 – Confirm the expected Jessica Lin message appears in the tool output from Milestone 0
                Milestone(
                    snapshot_constraints=[
                        SnapshotConstraint(
                            database_namespace=DatabaseNamespace.SANDBOX,
                            snapshot_constraint=partial(
